<?php
use Illuminate\Support\Facades\Route; use App\Http\Controllers\AuthController; use App\Http\Controllers\TrackingController; use App\Http\Controllers\Admin\DashboardController; use App\Http\Controllers\Admin\ShipmentController; use App\Http\Controllers\Admin\CustomerController; use App\Http\Controllers\Admin\AuditController;
Route::get('/',fn()=>redirect()->route('tracking.index')); Route::get('/track',[TrackingController::class,'index'])->middleware('throttle:tracking')->name('tracking.index');
Route::middleware('guest')->group(function(){Route::get('/login',[AuthController::class,'showLogin'])->name('login');Route::post('/login',[AuthController::class,'login'])->name('login.store');});Route::post('/logout',[AuthController::class,'logout'])->middleware('auth')->name('logout');
Route::middleware(['auth','admin'])->prefix('admin')->name('admin.')->group(function(){Route::get('/dashboard',[DashboardController::class,'index'])->name('dashboard');Route::get('/shipments',[ShipmentController::class,'index'])->name('shipments.index');Route::get('/shipments/create',[ShipmentController::class,'create'])->name('shipments.create');Route::post('/shipments',[ShipmentController::class,'store'])->name('shipments.store');Route::get('/shipments/{shipment}',[ShipmentController::class,'show'])->name('shipments.show');Route::patch('/shipments/{shipment}/status',[ShipmentController::class,'updateStatus'])->name('shipments.status');Route::resource('customers',CustomerController::class)->except(['show'])->names('customers');Route::get('/audit',[AuditController::class,'index'])->name('audit.index');});
